/**
 * Sort component that provides sorting controls for the collection items.
 * Wraps the Sort primitive with CMS collection state management.
 *
 * @component
 * @example
 * ```tsx
 * // Define sort options
 * const sortOptions = [
 *   { fieldName: 'title', order: 'ASC' as const, label: 'Title (A-Z)' },
 *   { fieldName: 'title', order: 'DESC' as const, label: 'Title (Z-A)' },
 *   { fieldName: 'price', order: 'ASC' as const, label: 'Price (Low to High)' },
 *   { fieldName: 'price', order: 'DESC' as const, label: 'Price (High to Low)' },
 *   { fieldName: '_createdDate', order: 'DESC' as const, label: 'Newest First' },
 *   { fieldName: '_createdDate', order: 'ASC' as const, label: 'Oldest First' },
 * ];
 *
 * // Custom implementation with render function (asChild is automatically true)
 * <CmsCollection.Sort sortOptions={sortOptions}>
 *   {({ currentSort, options, onChange }) => (
 *     <select
 *       value={`${currentSort?.fieldName ?? ''}-${currentSort?.order ?? ''}`}
 *       onChange={(e) => {
 *         const [fieldName, order] = e.target.value.split('-');
 *         onChange(fieldName || undefined, order || undefined);
 *       }}
 *     >
 *       {options.map((option, i) => (
 *         <option
 *           key={`${option.fieldName}-${option.order}-${i}`}
 *           value={`${option.fieldName ?? ''}-${option.order ?? ''}`}
 *         >
 *           {option.label}
 *         </option>
 *       ))}
 *     </select>
 *   )}
 * </CmsCollection.Sort>
 *
 * // Custom list container with render function
 * <CmsCollection.Sort sortOptions={sortOptions}>
 *   {({ currentSort, options, onChange }) => (
 *     <ul className="flex gap-2">
 *       {options.map((option, i) => (
 *         <li key={i}>
 *           <button
 *             onClick={() => onChange(option.fieldName, option.order)}
 *             className={option.isSelected ? 'bg-primary text-primary-foreground' : ''}
 *           >
 *             {option.label}
 *           </button>
 *         </li>
 *       ))}
 *     </ul>
 *   )}
 * </CmsCollection.Sort>
 * ```
 */
export declare const Sort: React.ForwardRefExoticComponent<SortProps & React.RefAttributes<HTMLElement>>;
